134	export function indexSemanticGraph(graph: SemanticGraph): SemanticGraphIndex {
135	  const regionById = new Map(graph.regions.map((region) => [region.id, region]));
136	  const objectById = new Map(graph.objects.map((object) => [object.id, object]));
137	  const relationshipById = new Map(graph.relationships.map((relationship) => [relationship.id, relationship]));
138	  const flowById = new Map(graph.flows.map((flow) => [flow.id, flow]));
139	  const incomingByObjectId = new Map<string, SemanticRelationship[]>();
140	  const outgoingByObjectId = new Map<string, SemanticRelationship[]>();
141	  const objectsByRegionId = new Map<string, SemanticObject[]>();
142	  const childRegionsByRegionId = new Map<string | null, SemanticRegion[]>();
143	
144	  for (const relationship of graph.relationships) {
145	    append(outgoingByObjectId, relationship.sourceObjectId, relationship);
146	    append(incomingByObjectId, relationship.targetObjectId, relationship);
147	    if (relationship.direction === "bidirectional") {
148	      append(incomingByObjectId, relationship.sourceObjectId, relationship);
149	      append(outgoingByObjectId, relationship.targetObjectId, relationship);
150	    }
151	  }
152	  for (const object of graph.objects) append(objectsByRegionId, object.regionId, object);
153	  for (const region of graph.regions) append(childRegionsByRegionId, region.parentRegionId ?? null, region);
154	
155	  return {
156	    regionById,
157	    objectById,
158	    relationshipById,
159	    flowById,
160	    incomingByObjectId,
161	    outgoingByObjectId,
162	    objectsByRegionId,
163	    childRegionsByRegionId,
164	  };
165	}
166	
167	export function semanticGraphFingerprint(graph: SemanticGraph) {
168	  return [
169	    graph.version,
170	    ...graph.regions
171	      .map((region) => `r:${region.id}:${region.parentRegionId ?? "root"}:${region.order ?? 0}`)
172	      .sort(),
173	    ...graph.objects
174	      .map((object) => `o:${object.id}:${object.regionId}:${object.objectType}:${object.name}:${object.summary ?? ""}:${object.layoutHints?.order ?? 0}`)
175	      .sort(),
176	    ...graph.relationships
177	      .map((relationship) => `e:${relationship.id}:${relationship.sourceObjectId}:${relationship.targetObjectId}:${relationship.relationshipType}`)
178	      .sort(),
179	  ].join("|");
180	}
181	
182	export function validateSemanticGraph(graph: SemanticGraph) {
183	  const errors: string[] = [];
184	  const duplicateIds = (ids: string[], kind: string) => {
185	    const seen = new Set<string>();
186	    for (const id of ids) {
187	      if (seen.has(id)) errors.push(`${kind} id is duplicated: ${id}`);
188	      seen.add(id);
189	    }
190	  };
191	  duplicateIds(graph.regions.map((region) => region.id), "Region");
192	  duplicateIds(graph.objects.map((object) => object.id), "Object");
193	  duplicateIds(graph.relationships.map((relationship) => relationship.id), "Relationship");
194	  duplicateIds(graph.flows.map((flow) => flow.id), "Flow");
195	
196	  const regionIds = new Set(graph.regions.map((region) => region.id));
197	  const objectIds = new Set(graph.objects.map((object) => object.id));
198	  const relationshipIds = new Set(graph.relationships.map((relationship) => relationship.id));
199	
200	  for (const region of graph.regions) {
201	    if (region.parentRegionId && !regionIds.has(region.parentRegionId)) errors.push(`Region ${region.id} references missing parent ${region.parentRegionId}`);
202	    const seen = new Set<string>([region.id]);
203	    let parentId = region.parentRegionId;
204	    while (parentId) {
205	      if (seen.has(parentId)) {
206	        errors.push(`Region hierarchy contains a cycle at ${region.id}`);
207	        break;
208	      }
209	      seen.add(parentId);
210	      parentId = graph.regions.find((candidate) => candidate.id === parentId)?.parentRegionId;
211	    }
212	  }
213	  for (const object of graph.objects) {
214	    if (!regionIds.has(object.regionId)) errors.push(`Object ${object.id} references missing region ${object.regionId}`);
215	  }
216	  for (const relationship of graph.relationships) {
217	    if (!objectIds.has(relationship.sourceObjectId)) errors.push(`Relationship ${relationship.id} references missing source ${relationship.sourceObjectId}`);
218	    if (!objectIds.has(relationship.targetObjectId)) errors.push(`Relationship ${relationship.id} references missing target ${relationship.targetObjectId}`);
219	  }
220	  for (const flow of graph.flows) {
221	    for (const objectId of flow.objectIds) if (!objectIds.has(objectId)) errors.push(`Flow ${flow.id} references missing object ${objectId}`);
222	    for (const relationshipId of flow.relationshipIds) if (!relationshipIds.has(relationshipId)) errors.push(`Flow ${flow.id} references missing relationship ${relationshipId}`);
223	    const stepIds = new Set(flow.steps.map((step) => step.id));
224	    if (stepIds.size !== flow.steps.length) errors.push(`Flow ${flow.id} contains duplicate step ids`);
225	    for (const step of flow.steps) {
226	      if (!objectIds.has(step.objectId)) errors.push(`Flow step ${step.id} references missing object ${step.objectId}`);
227	      for (const nextStepId of step.nextStepIds) if (!stepIds.has(nextStepId)) errors.push(`Flow step ${step.id} references missing next step ${nextStepId}`);
228	    }
229	  }
230	  return errors;
231	}
