3	import type { CanvasLayout } from "./layout";
4	import { indexSemanticGraph, type SemanticFlowStep, type SemanticGraph } from "./semantic-graph";
5	import type { ObjectNodeData, RegionNodeData, RelationshipEdgeData } from "./types";
6	
7	export type CanvasObjectNode = Node<ObjectNodeData, "object">;
8	export type CanvasRegionNode = Node<RegionNodeData, "region">;
9	export type CanvasNode = CanvasObjectNode | CanvasRegionNode;
10	export type CanvasRelationshipEdge = Edge<RelationshipEdgeData, "relationship">;
