12	function handleId(side: "left" | "right" | "top" | "bottom", role: "source" | "target") {
13	  return `${role}-${side}`;
14	}
15	
16	function flowTransition(
17	  steps: SemanticFlowStep[],
18	  sourceObjectId: string,
19	  targetObjectId: string,
20	) {
21	  const stepById = new Map(steps.map((step) => [step.id, step]));
22	  for (const step of steps) {
23	    if (step.objectId !== sourceObjectId) continue;
24	    const next = step.nextStepIds.map((id) => stepById.get(id)).find((candidate) => candidate?.objectId === targetObjectId);
25	    if (!next) continue;
26	    const payload = step.outputs.length > 0 ? step.outputs.join(" + ") : next.inputs.join(" + ");
27	    return { sequence: step.sequence, payload, detail: `${step.title} → ${next.title}` };
28	  }
29	  return null;
30	}
31	
32	export function projectSemanticGraph(
33	  graph: SemanticGraph,
34	  layout: CanvasLayout,
35	  view: CanvasViewModel,
36	): { nodes: CanvasNode[]; edges: CanvasRelationshipEdge[] } {
37	  const index = indexSemanticGraph(graph);
38	  const visibleIds = visibleObjectIds(graph, view);
39	  const activeFlow = view.activeFlowId ? index.flowById.get(view.activeFlowId) : undefined;
40	  const regionNodes = graph.regions
41	    .map<CanvasRegionNode | null>((region) => {
42	      const rect = layout.regionRects[region.id];
