3	import { type ReactFlowInstance, useEdgesState, useNodesState } from "@xyflow/react";
4	import Link from "next/link";
5	import { useCallback, useEffect, useMemo, useRef, useState } from "react";
6	import ArchitectureCanvasKernel from "./canvas-kernel";
7	import FlowPanel from "./flow-panel";
8	import { atRevision } from "./flow-projection";
9	import Inspector from "./inspector";
10	import { bindInspector } from "./inspector-binding";
11	import { deriveCanvasView, type CanvasInteractionState, type CanvasSelection } from "./interaction";
12	import { layoutSemanticGraph, type CanvasLayout } from "./layout";
13	import { projectSemanticGraph, type CanvasNode, type CanvasObjectNode, type CanvasRelationshipEdge } from "./projection";
14	import { adaptArchitectureToSemanticGraph } from "./semantic-adapter";
15	import { semanticGraphFingerprint, type SemanticGraph } from "./semantic-graph";
16	import type {
17	  ArchitectureEntity,
18	  ArchitectureFlow,
19	  ArchitectureFlowStep,
20	  ArchitectureRelation,
21	  ProjectDetail,
22	} from "./types";
23	
24	const EMPTY_ARCHITECTURE = {
25	  entities: [] as ArchitectureEntity[],
26	  relations: [] as ArchitectureRelation[],
27	  flows: [] as ArchitectureFlow[],
28	  flowSteps: [] as ArchitectureFlowStep[],
29	};
30	
31	const layoutMemory = new Map<string, CanvasLayout>();
32	
33	function latestModel<T extends { lifecycleStatus: string }>(
34	  active: T[],
35	  pending: T[],
36	  key: (item: T) => string,
37	  showPending: boolean,
38	) {
39	  if (!showPending) return active;
40	  const result = new Map(active.map((item) => [key(item), item]));
41	  for (const item of pending) result.set(key(item), item);
42	  return [...result.values()];
43	}
44	
45	function revisionSnapshot<T extends { validFromRevision: number; validToRevision: number | null; lifecycleStatus: string }>(
46	  rows: T[],
47	  revision: number,
48	  currentRevision: number,
49	) {
50	  if (revision === currentRevision) return rows.filter((row) => row.lifecycleStatus === "ACTIVE");
51	  return atRevision(rows.filter((row) => row.lifecycleStatus !== "PENDING"), revision);
52	}
53	
54	function sameEntity(left: ArchitectureEntity, right: ArchitectureEntity) {
55	  return left.name === right.name
56	    && left.summary === right.summary
57	    && left.entityType === right.entityType
58	    && left.parentEntityKey === right.parentEntityKey
59	    && left.technology === right.technology
60	    && left.repositoryRefsJson === right.repositoryRefsJson
61	    && left.knowledgeState === right.knowledgeState;
62	}
63	
64	function layoutStorageKey(graph: SemanticGraph) {
65	  return `ecp:canvas-engine-v1:${graph.scope.projectId}:r${graph.scope.revision}`;
66	}
67	
68	function readLayout(key: string, fingerprint: string) {
69	  try {
70	    const parsed = JSON.parse(window.localStorage.getItem(key) ?? "null") as CanvasLayout | null;
71	    return parsed?.fingerprint === fingerprint ? parsed : null;
72	  } catch {
73	    return null;
74	  }
75	}
76	
77	function writeLayout(key: string, layout: CanvasLayout) {
78	  layoutMemory.set(`${key}:${layout.fingerprint}`, layout);
79	  try {
80	    window.localStorage.setItem(key, JSON.stringify(layout));
81	  } catch {
82	    // Storage is a convenience, never a canonical architecture write.
83	  }
84	}
85	
86	export default function ArchitectureCanvas({
87	  detail,
88	  graphOverride,
89	}: {
90	  detail?: ProjectDetail;
91	  graphOverride?: SemanticGraph;
92	}) {
93	  const architecture = detail?.architecture ?? EMPTY_ARCHITECTURE;
94	  const currentRevision = detail?.project.revision ?? graphOverride?.scope.revision ?? 1;
95	  const revisionOptions = useMemo(() => {
96	    if (!detail) return [currentRevision];
97	    const known = detail.revisions.map((revision) => revision.revisionNumber).filter((revision) => revision <= currentRevision);
98	    return [...new Set([...known, currentRevision])].sort((left, right) => left - right);
99	  }, [currentRevision, detail]);
100	  const [revisionIndex, setRevisionIndex] = useState(Math.max(0, revisionOptions.length - 1));
101	  const viewRevision = revisionOptions[Math.min(revisionIndex, revisionOptions.length - 1)] ?? currentRevision;
102	  const isCurrentRevision = viewRevision === currentRevision;
103	  const [playingTimeline, setPlayingTimeline] = useState(false);
104	  const [showPending, setShowPending] = useState(false);
105	  const [flowLensOpen, setFlowLensOpen] = useState(false);
106	  const [layouting, setLayouting] = useState(true);
107	  const [layoutError, setLayoutError] = useState("");
108	  const [layoutReset, setLayoutReset] = useState(0);
109	  const [layout, setLayout] = useState<CanvasLayout | null>(null);
110	  const [interaction, setInteraction] = useState<CanvasInteractionState>({
111	    mode: "browse",
112	    selection: null,
113	    activeFlowId: null,
114	    zoom: 0.72,
115	    searchQuery: "",
116	  });
117	  const [nodes, setNodes, onNodesChange] = useNodesState<CanvasNode>([]);
118	  const [edges, setEdges, onEdgesChange] = useEdgesState<CanvasRelationshipEdge>([]);
119	  const instanceRef = useRef<ReactFlowInstance<CanvasNode, CanvasRelationshipEdge> | null>(null);
120	  const canvasRef = useRef<HTMLDivElement | null>(null);
121	  const previousLayoutRef = useRef<CanvasLayout | null>(null);
122	  const fittedLayoutRef = useRef("");
123	
124	  const baseEntities = useMemo(
125	    () => revisionSnapshot(architecture.entities, viewRevision, currentRevision),
126	    [architecture.entities, currentRevision, viewRevision],
127	  );
128	  const baseRelations = useMemo(
129	    () => revisionSnapshot(architecture.relations, viewRevision, currentRevision),
130	    [architecture.relations, currentRevision, viewRevision],
131	  );
132	  const baseFlows = useMemo(
133	    () => revisionSnapshot(architecture.flows, viewRevision, currentRevision),
134	    [architecture.flows, currentRevision, viewRevision],
135	  );
136	  const baseFlowSteps = useMemo(
137	    () => revisionSnapshot(architecture.flowSteps, viewRevision, currentRevision),
138	    [architecture.flowSteps, currentRevision, viewRevision],
139	  );
140	  const pendingEntities = useMemo(() => architecture.entities.filter((entity) => entity.lifecycleStatus === "PENDING"), [architecture.entities]);
141	  const pendingRelations = useMemo(() => architecture.relations.filter((relation) => relation.lifecycleStatus === "PENDING"), [architecture.relations]);
142	  const pendingFlows = useMemo(() => architecture.flows.filter((flow) => flow.lifecycleStatus === "PENDING"), [architecture.flows]);
143	  const pendingFlowSteps = useMemo(() => architecture.flowSteps.filter((step) => step.lifecycleStatus === "PENDING"), [architecture.flowSteps]);
144	  const showChangeOverlay = showPending && isCurrentRevision;
145	  const entities = useMemo(() => latestModel(baseEntities, pendingEntities, (entity) => entity.entityKey, showChangeOverlay), [baseEntities, pendingEntities, showChangeOverlay]);
146	  const relations = useMemo(() => latestModel(baseRelations, pendingRelations, (relation) => relation.relationKey, showChangeOverlay), [baseRelations, pendingRelations, showChangeOverlay]);
147	  const flows = useMemo(() => latestModel(baseFlows, pendingFlows, (flow) => flow.flowKey, showChangeOverlay), [baseFlows, pendingFlows, showChangeOverlay]);
148	  const flowSteps = useMemo(() => latestModel(baseFlowSteps, pendingFlowSteps, (step) => `${step.flowKey}:${step.stepKey}`, showChangeOverlay), [baseFlowSteps, pendingFlowSteps, showChangeOverlay]);
149	
150	  const previousRevision = useMemo(() => {
151	    const index = revisionOptions.indexOf(viewRevision) - 1;
152	    return index >= 0 ? revisionOptions[index] : null;
153	  }, [revisionOptions, viewRevision]);
154	  const timelineStates = useMemo(() => {
155	    const states = new Map<string, "added" | "changed">();
156	    if (previousRevision === null || graphOverride) return states;
157	    const previous = new Map(atRevision(architecture.entities.filter((entity) => entity.lifecycleStatus !== "PENDING"), previousRevision).map((entity) => [entity.entityKey, entity]));
158	    for (const entity of entities) {
159	      const prior = previous.get(entity.entityKey);
160	      if (!prior) states.set(entity.entityKey, "added");
161	      else if (!sameEntity(prior, entity)) states.set(entity.entityKey, "changed");
162	    }
163	    return states;
164	  }, [architecture.entities, entities, graphOverride, previousRevision]);
165	
166	  const graph = useMemo(() => graphOverride ?? adaptArchitectureToSemanticGraph({
167	    projectId: detail?.project.id ?? "fixture",
168	    projectName: detail?.project.name ?? "Canvas Fixture",
169	    revision: viewRevision,
170	    entities,
171	    relations,
172	    flows,
173	    flowSteps,
174	    timelineStates,
175	  }), [detail?.project.id, detail?.project.name, entities, flowSteps, flows, graphOverride, relations, timelineStates, viewRevision]);
176	  const fingerprint = useMemo(() => semanticGraphFingerprint(graph), [graph]);
177	  const storageKey = useMemo(() => layoutStorageKey(graph), [graph]);
178	  const view = useMemo(() => deriveCanvasView(graph, interaction), [graph, interaction]);
179	  const inspectorBinding = useMemo(() => bindInspector(graph, interaction.selection), [graph, interaction.selection]);
180	  const projection = useMemo(() => layout ? projectSemanticGraph(graph, layout, view) : { nodes: [], edges: [] }, [graph, layout, view]);
181	  const searchResults = useMemo(() => interaction.searchQuery.trim()
182	    ? graph.objects.filter((object) => view.searchMatches.has(object.id)).slice(0, 8)
183	    : [], [graph.objects, interaction.searchQuery, view.searchMatches]);
184	
185	  useEffect(() => {
186	    if (!playingTimeline) return;
187	    const timer = window.setInterval(() => {
188	      setRevisionIndex((index) => {
189	        if (index >= revisionOptions.length - 1) {
190	          setPlayingTimeline(false);
191	          return index;
192	        }
193	        return index + 1;
194	      });
195	    }, 1300);
196	    return () => window.clearInterval(timer);
197	  }, [playingTimeline, revisionOptions.length]);
198	
199	  useEffect(() => {
200	    let cancelled = false;
201	    const cacheKey = `${storageKey}:${fingerprint}`;
202	    const cached = layoutReset === 0 ? layoutMemory.get(cacheKey) ?? readLayout(storageKey, fingerprint) : null;
203	    if (cached) {
204	      previousLayoutRef.current = cached;
205	      const timer = window.setTimeout(() => {
206	        setLayout(cached);
207	        setLayouting(false);
208	        setLayoutError("");
209	      }, 0);
210	      return () => window.clearTimeout(timer);
211	    }
212	    const loadingTimer = window.setTimeout(() => setLayouting(true), 0);
213	    void layoutSemanticGraph(graph, { previousLayout: previousLayoutRef.current ?? undefined })
214	      .then((nextLayout) => {
215	        if (cancelled) return;
216	        previousLayoutRef.current = nextLayout;
217	        writeLayout(storageKey, nextLayout);
218	        setLayout(nextLayout);
219	        setLayoutError("");
220	        setLayouting(false);
221	      })
222	      .catch(() => {
223	        if (cancelled) return;
224	        setLayout(previousLayoutRef.current);
225	        setLayoutError("ELK could not arrange this graph. The last stable local layout is preserved.");
226	        setLayouting(false);
227	      });
228	    return () => { cancelled = true; window.clearTimeout(loadingTimer); };
229	  }, [fingerprint, graph, layoutReset, storageKey]);
230	
231	  useEffect(() => {
232	    setNodes(projection.nodes);
233	    setEdges(projection.edges);
234	    const layoutIdentity = layout ? `${storageKey}:${layout.fingerprint}` : "";
235	    if (layoutIdentity && fittedLayoutRef.current !== layoutIdentity) {
236	      fittedLayoutRef.current = layoutIdentity;
237	      const timer = window.setTimeout(() => instanceRef.current?.fitView({ padding: 0.16, duration: 360, maxZoom: 1.05 }), 40);
238	      return () => window.clearTimeout(timer);
239	    }
240	    return undefined;
241	  }, [layout, projection, setEdges, setNodes, storageKey]);
242	
243	  useEffect(() => {
244	    const availableObjects = new Set(graph.objects.map((object) => object.id));
245	    const availableRelationships = new Set(graph.relationships.map((relationship) => relationship.id));
246	    const availableFlows = new Set(graph.flows.map((flow) => flow.id));
247	    const selection = interaction.selection;
248	    const valid = !selection
249	      || (selection.kind === "object" && availableObjects.has(selection.id))
250	      || (selection.kind === "relationship" && availableRelationships.has(selection.id))
251	      || (selection.kind === "flow" && availableFlows.has(selection.id));
252	    if (!valid || (interaction.activeFlowId && !availableFlows.has(interaction.activeFlowId))) {
253	      const timer = window.setTimeout(() => setInteraction((current) => ({ ...current, mode: "browse", selection: null, activeFlowId: null })), 0);
254	      return () => window.clearTimeout(timer);
255	    }
256	    return undefined;
257	  }, [graph, interaction.activeFlowId, interaction.selection]);
258	
259	  const select = useCallback((selection: CanvasSelection) => {
260	    if (selection?.kind === "flow") {
261	      const flowObjectIds = new Set(graph.flows.find((flow) => flow.id === selection.id)?.objectIds ?? []);
262	      window.setTimeout(() => {
263	        const instance = instanceRef.current;
264	        const targetNodes = instance?.getNodes().filter((node) => flowObjectIds.has(node.id)) ?? [];
265	        if (targetNodes.length > 0) void instance?.fitView({ nodes: targetNodes, padding: .38, duration: 420, maxZoom: 1.08 });
266	      }, 80);
267	    }
268	    setInteraction((current) => {
269	      if (!selection) return { ...current, mode: "browse", selection: null, activeFlowId: null };
270	      if (selection.kind === "flow") return { ...current, mode: "trace", selection, activeFlowId: selection.id };
271	      if (current.mode === "trace") return { ...current, selection };
272	      if (current.mode === "focus" && selection.kind === "object") return { ...current, selection, activeFlowId: null };
273	      return { ...current, mode: "inspect", selection, activeFlowId: null };
274	    });
275	  }, [graph.flows]);
276	
277	  const focusObject = useCallback((objectId: string) => {
278	    const focusIds = new Set([objectId]);
279	    for (const relationship of graph.relationships) {
280	      if (relationship.sourceObjectId === objectId) focusIds.add(relationship.targetObjectId);
281	      if (relationship.targetObjectId === objectId) focusIds.add(relationship.sourceObjectId);
282	    }
283	    window.setTimeout(() => {
284	      const instance = instanceRef.current;
285	      const targetNodes = instance?.getNodes().filter((node) => focusIds.has(node.id)) ?? [];
286	      if (targetNodes.length > 0) void instance?.fitView({ nodes: targetNodes, padding: .48, duration: 380, maxZoom: 1.15 });
287	    }, 80);
288	    setInteraction((current) => ({ ...current, mode: "focus", selection: { kind: "object", id: objectId }, activeFlowId: null }));
289	  }, [graph.relationships]);
290	
291	  useEffect(() => {
292	    const onKeyDown = (event: KeyboardEvent) => {
293	      const target = event.target as HTMLElement | null;
294	      if (target?.matches("input, textarea, select, [contenteditable='true']")) return;
295	      if (event.key.toLowerCase() === "f" && interaction.selection?.kind === "object") focusObject(interaction.selection.id);
296	      if (event.key === "Escape") select(null);
297	    };
298	    window.addEventListener("keydown", onKeyDown);
299	    return () => window.removeEventListener("keydown", onKeyDown);
300	  }, [focusObject, interaction.selection, select]);
301	
302	  function handleNodeDragStop(node: CanvasObjectNode) {
303	    if (!layout) return;
304	    const previousRect = layout.objectRects[node.id];
305	    if (!previousRect) return;
306	    const incidentRelationshipIds = new Set(graph.relationships
307	      .filter((relationship) => relationship.sourceObjectId === node.id || relationship.targetObjectId === node.id)
308	      .map((relationship) => relationship.id));
309	    const nextLayout: CanvasLayout = {
310	      ...layout,
311	      objectRects: { ...layout.objectRects, [node.id]: { ...previousRect, x: node.position.x, y: node.position.y } },
312	      relationshipRoutes: Object.fromEntries(Object.entries(layout.relationshipRoutes).filter(([id]) => !incidentRelationshipIds.has(id))),
313	    };
314	    previousLayoutRef.current = nextLayout;
315	    writeLayout(storageKey, nextLayout);
316	    setLayout(nextLayout);
317	  }
318	
319	  function resetLayout() {
320	    try { window.localStorage.removeItem(storageKey); } catch { /* no-op */ }
321	    layoutMemory.delete(`${storageKey}:${fingerprint}`);
322	    previousLayoutRef.current = null;
323	    fittedLayoutRef.current = "";
324	    setLayoutReset((value) => value + 1);
325	  }
326	
327	  function handlePaneClick() {
328	    if (interaction.mode === "trace") setInteraction((current) => ({ ...current, selection: null }));
329	    else select(null);
330	  }
331	
332	  async function toggleFullscreen() {
