335	  }
336	
337	  if (!graphOverride && isCurrentRevision && baseEntities.length === 0 && !showPending) {
338	    return (
339	      <section className="architecture-empty-state">
340	        <small>Architecture Model 尚未建立</small>
341	        <h2>这个 Project 还没有可发布的架构对象</h2>
342	        <p>Human Web 不负责画图。维护 Agent 应通过 revision-pinned Change 提交 Architecture Observation、Evidence 和关系模型。</p>
343	        {pendingEntities.length > 0 && <button onClick={() => setShowPending(true)} type="button">预览 {pendingEntities.length} 个待发布对象</button>}
344	        {detail && <Link href={`/maintenance?project=${encodeURIComponent(detail.project.id)}&tab=facts`}>查看 Project Registry</Link>}
345	      </section>
346	    );
347	  }
348	
349	  return (
350	    <div className="architecture-workbench" ref={canvasRef}>
351	      <header className="canvas-commandbar">
352	        <nav className="canvas-modes" aria-label="Canvas mode">
353	          <button className={interaction.mode === "browse" ? "active" : ""} onClick={() => select(null)} type="button">Browse</button>
354	          <button className={interaction.mode === "inspect" ? "active" : ""} disabled={!interaction.selection || interaction.selection.kind === "flow"} onClick={() => setInteraction((current) => ({ ...current, mode: "inspect", activeFlowId: null }))} type="button">Inspect</button>
355	          <button className={interaction.mode === "focus" ? "active" : ""} disabled={interaction.selection?.kind !== "object"} onClick={() => interaction.selection?.kind === "object" && focusObject(interaction.selection.id)} type="button">Focus</button>
356	          <button className={interaction.mode === "trace" ? "active" : ""} onClick={() => setFlowLensOpen((open) => !open)} type="button">Trace <b>{graph.flows.length}</b></button>
357	        </nav>
358	        <div className="canvas-search">
359	          <input aria-label="Search architecture objects" onChange={(event) => setInteraction((current) => ({ ...current, searchQuery: event.target.value }))} placeholder="Search objects…" value={interaction.searchQuery} />
360	          {searchResults.length > 0 && (
361	            <div className="canvas-search-results">
362	              {searchResults.map((object) => <button key={object.id} onClick={() => { select({ kind: "object", id: object.id }); setInteraction((current) => ({ ...current, searchQuery: "" })); }} type="button"><span>{object.objectType}</span><strong>{object.name}</strong></button>)}
363	            </div>
364	          )}
365	        </div>
366	        <div className="canvas-command-actions">
367	          {detail && isCurrentRevision && pendingEntities.length > 0 && <button className={showPending ? "active" : ""} onClick={() => setShowPending((value) => !value)} type="button">Change Overlay <b>{pendingEntities.length}</b></button>}
368	          <button onClick={() => instanceRef.current?.fitView({ padding: 0.16, duration: 300, maxZoom: 1.05 })} type="button">Fit</button>
369	          <button onClick={resetLayout} type="button">Layout</button>
370	          <button onClick={() => void toggleFullscreen()} type="button">Full</button>
371	        </div>
372	      </header>
373	
374	      {detail && revisionOptions.length > 1 && (
375	        <div className="revision-timeline">
376	          <button aria-label={playingTimeline ? "暂停 Revision Timeline" : "播放 Revision Timeline"} onClick={() => {
377	            if (revisionIndex >= revisionOptions.length - 1) setRevisionIndex(0);
