import type {
  ArchitectureEntity,
  ArchitectureFlow,
  ArchitectureFlowStep,
  ArchitectureRelation,
} from "./types";
import {
  SEMANTIC_GRAPH_VERSION,
  type SemanticFlow,
  type SemanticFlowStep,
  type SemanticGraph,
  type SemanticImportance,
  type SemanticObject,
  type SemanticObjectType,
  type SemanticRegion,
  type SemanticRelationship,
  type SemanticRelationshipType,
  type SemanticState,
} from "./semantic-graph";

export type ArchitectureSemanticInput = {
  projectId: string;
  projectName: string;
  revision: number;
  entities: ArchitectureEntity[];
  relations: ArchitectureRelation[];
  flows: ArchitectureFlow[];
  flowSteps: ArchitectureFlowStep[];
  timelineStates?: Map<string, "added" | "changed">;
  source?: "registry" | "fixture";
};

const KNOWLEDGE_COPY: Record<string, string> = {
  AUTHORITATIVE: "规则",
  CONFIRMED: "已验证",
  INFERRED: "推断",
  UNKNOWN: "未知",
  STALE: "可能过期",
  CONFLICTED: "存在冲突",
};

const RELATIONSHIP_TYPE_MAP: Record<string, SemanticRelationshipType> = {
  reads: "data",
  writes: "data",
  produces: "data",
  persists: "data",
  stores: "data",
  supported_by: "data",
  calls: "control",
  exposes: "control",
  triggers: "control",
  traverses: "control",
  delegates: "control",
  emits: "event",
  publishes: "event",
  subscribes: "event",
  notifies: "event",
  depends_on: "dependency",
  constrained_by: "dependency",
  contains: "dependency",
  external: "external",
};

function parseStringArray(value: string) {
  try {
    const parsed = JSON.parse(value);
    return Array.isArray(parsed) ? parsed.filter((item): item is string => typeof item === "string") : [];
  } catch {
    return [];
  }
}

function stateFromKnowledge(knowledgeState: string, timelineState?: "added" | "changed"): SemanticState {
  if (timelineState) {
    return {
      value: timelineState,
      label: timelineState === "added" ? "本 Revision 新增" : "本 Revision 变化",
      severity: "attention",
      source: "change",
    };
  }
  const normalized = knowledgeState.toUpperCase();
  if (normalized === "CONFLICTED") return { value: "conflicted", label: KNOWLEDGE_COPY[normalized], severity: "critical", source: "knowledge" };
  if (["INFERRED", "UNKNOWN", "STALE"].includes(normalized)) return { value: normalized.toLowerCase(), label: KNOWLEDGE_COPY[normalized], severity: "attention", source: "knowledge" };
  return { value: normalized.toLowerCase(), label: KNOWLEDGE_COPY[normalized] ?? normalized, severity: "positive", source: "knowledge" };
}

function objectType(entity: ArchitectureEntity): SemanticObjectType {
  const text = `${entity.entityType} ${entity.name} ${entity.technology}`.toLowerCase();
  if (entity.entityType === "DataEntity" || /database|storage|store|d1|postgres|redis|queue|artifact/.test(text)) return "storage";
  if (entity.entityType === "External" || /\bexternal\b|third[- ]party|github|gitlab|slack|jira/.test(text)) return "external";
  if (entity.entityType === "Agent" || /\bagent\b|claude|codex|llm|model runtime/.test(text)) return "agent";
  return "service";
}

function relationshipType(relationType: string): SemanticRelationshipType {
  return RELATIONSHIP_TYPE_MAP[relationType.toLowerCase()] ?? "dependency";
}

function relationshipPortHints(type: SemanticRelationshipType) {
  if (type === "event") return { sourcePortRole: "event" as const, targetPortRole: "event" as const, sourcePortSide: "bottom" as const, targetPortSide: "top" as const };
  if (type === "dependency") return { sourcePortRole: "downstream" as const, targetPortRole: "upstream" as const, sourcePortSide: "bottom" as const, targetPortSide: "top" as const };
  if (type === "control") return { sourcePortRole: "control" as const, targetPortRole: "control" as const, sourcePortSide: "right" as const, targetPortSide: "left" as const };
  return { sourcePortRole: "output" as const, targetPortRole: "input" as const, sourcePortSide: "right" as const, targetPortSide: "left" as const };
}

function importance(score: number): SemanticImportance {
  if (score >= 85) return { level: "critical", score };
  if (score >= 65) return { level: "high", score };
  if (score < 35) return { level: "low", score };
  return { level: "normal", score };
}

function regionOrder(entity: ArchitectureEntity, index: number) {
  const explicit = Number((entity as ArchitectureEntity & { order?: unknown }).order);
  return Number.isFinite(explicit) ? explicit : index;
}

function semanticFlowStep(step: ArchitectureFlowStep): SemanticFlowStep {
  return {
    id: step.stepKey,
    objectId: step.entityKey,
    sequence: step.sequence,
    role: step.role,
    title: step.title,
    inputs: parseStringArray(step.inputsJson),
    action: step.action,
    outputs: parseStringArray(step.outputsJson),
    stateReads: parseStringArray(step.stateReadsJson),
    stateWrites: parseStringArray(step.stateWritesJson),
    failureModes: parseStringArray(step.failureModesJson),
    nextStepIds: parseStringArray(step.nextStepKeysJson),
    metadata: {
      knowledgeState: step.knowledgeState,
      lifecycleStatus: step.lifecycleStatus,
      sourceObservationId: step.sourceObservationId,
    },
  };
}

export function adaptArchitectureToSemanticGraph(input: ArchitectureSemanticInput): SemanticGraph {
  const entities = [...input.entities].sort((left, right) => left.entityKey.localeCompare(right.entityKey));
  const entityByKey = new Map(entities.map((entity) => [entity.entityKey, entity]));
  const regionEntities = entities.filter((entity) => entity.entityType === "Domain" || entity.entityType === "Project");
  const regionEntityKeys = new Set(regionEntities.map((entity) => entity.entityKey));
  const syntheticRegionId = `${input.projectId}:region:unscoped`;

  function nearestRegionId(entity: ArchitectureEntity) {
    let cursor = entity.parentEntityKey ? entityByKey.get(entity.parentEntityKey) : undefined;
    const seen = new Set<string>();
    while (cursor && !seen.has(cursor.entityKey)) {
      if (regionEntityKeys.has(cursor.entityKey)) return cursor.entityKey;
      seen.add(cursor.entityKey);
      cursor = cursor.parentEntityKey ? entityByKey.get(cursor.parentEntityKey) : undefined;
    }
    return syntheticRegionId;
  }

  const regions: SemanticRegion[] = regionEntities.map((entity, index) => ({
    id: entity.entityKey,
    name: entity.name,
    summary: entity.summary,
    parentRegionId: entity.parentEntityKey && regionEntityKeys.has(entity.parentEntityKey) ? entity.parentEntityKey : undefined,
    order: regionOrder(entity, index),
    importance: importance(entity.parentEntityKey ? 66 : 88),
    metadata: {
      canonicalEntityType: entity.entityType,
      canonicalEntityKey: entity.entityKey,
      knowledgeState: entity.knowledgeState,
      lifecycleStatus: entity.lifecycleStatus,
      sourceObservationId: entity.sourceObservationId,
      validFromRevision: entity.validFromRevision,
      validToRevision: entity.validToRevision,
    },
  }));

  const objectEntities = entities.filter((entity) => !regionEntityKeys.has(entity.entityKey));
  if (objectEntities.some((entity) => nearestRegionId(entity) === syntheticRegionId) || regions.length === 0) {
    regions.push({
      id: syntheticRegionId,
      name: regions.length === 0 ? input.projectName : "Project Services",
      summary: regions.length === 0 ? "Project scope" : "Objects without an explicit Domain boundary.",
      order: Number.MAX_SAFE_INTEGER,
      importance: importance(regions.length === 0 ? 88 : 40),
      metadata: { synthetic: true },
    });
  }

  const degree = new Map<string, number>();
  for (const relation of input.relations) {
    degree.set(relation.sourceEntityKey, (degree.get(relation.sourceEntityKey) ?? 0) + 1);
    degree.set(relation.targetEntityKey, (degree.get(relation.targetEntityKey) ?? 0) + 1);
  }

  const objects: SemanticObject[] = objectEntities.map((entity, index) => {
    const entityDegree = degree.get(entity.entityKey) ?? 0;
    const score = Math.min(98, 42 + entityDegree * 7 + (entity.entityType === "DataEntity" ? 9 : 0));
    return {
      id: entity.entityKey,
      name: entity.name,
      summary: entity.summary,
      objectType: objectType(entity),
      regionId: nearestRegionId(entity),
      state: stateFromKnowledge(entity.knowledgeState, input.timelineStates?.get(entity.entityKey)),
      importance: importance(score),
      metadata: {
        canonicalEntityType: entity.entityType,
        canonicalEntityKey: entity.entityKey,
        technology: entity.technology,
        repositoryRefs: parseStringArray(entity.repositoryRefsJson),
        knowledgeState: entity.knowledgeState,
        lifecycleStatus: entity.lifecycleStatus,
        sourceObservationId: entity.sourceObservationId,
        validFromRevision: entity.validFromRevision,
        validToRevision: entity.validToRevision,
        degree: entityDegree,
        parentEntityKey: entity.parentEntityKey,
      },
      layoutHints: { order: index },
    };
  });

  const objectIds = new Set(objects.map((object) => object.id));
  const relationships: SemanticRelationship[] = input.relations
    .filter((relation) => objectIds.has(relation.sourceEntityKey) && objectIds.has(relation.targetEntityKey))
    .map((relation, index) => {
      const type = relationshipType(relation.relationType);
      return {
        id: relation.relationKey,
        sourceObjectId: relation.sourceEntityKey,
        targetObjectId: relation.targetEntityKey,
        relationshipType: type,
        direction: "directed",
        label: relation.label || relation.relationType.replaceAll("_", " "),
        summary: relation.summary,
        state: stateFromKnowledge(relation.knowledgeState),
        importance: importance(type === "control" || type === "event" ? 62 : 54),
        metadata: {
          canonicalRelationType: relation.relationType,
          knowledgeState: relation.knowledgeState,
          evidenceRefs: parseStringArray(relation.evidenceRefsJson),
          lifecycleStatus: relation.lifecycleStatus,
          sourceObservationId: relation.sourceObservationId,
          validFromRevision: relation.validFromRevision,
          validToRevision: relation.validToRevision,
          flowIds: [] as string[],
        },
        layoutHints: { ...relationshipPortHints(type), order: index },
      } satisfies SemanticRelationship;
    });

  const relationshipByEndpoints = new Map<string, SemanticRelationship[]>();
  for (const relationship of relationships) {
    const key = `${relationship.sourceObjectId}\u0000${relationship.targetObjectId}`;
    relationshipByEndpoints.set(key, [...(relationshipByEndpoints.get(key) ?? []), relationship]);
  }

  const flowStepsByFlow = new Map<string, ArchitectureFlowStep[]>();
  for (const step of input.flowSteps) {
    const values = flowStepsByFlow.get(step.flowKey) ?? [];
    values.push(step);
    flowStepsByFlow.set(step.flowKey, values);
  }

  const flows: SemanticFlow[] = input.flows.map((flow) => {
    const steps = (flowStepsByFlow.get(flow.flowKey) ?? [])
      .filter((step) => objectIds.has(step.entityKey))
      .sort((left, right) => left.sequence - right.sequence || left.stepKey.localeCompare(right.stepKey));
    const semanticSteps = steps.map(semanticFlowStep);
    const stepById = new Map(steps.map((step) => [step.stepKey, step]));
    const relationshipIds = new Set<string>();

    for (const step of steps) {
      for (const nextStepKey of parseStringArray(step.nextStepKeysJson)) {
        const next = stepById.get(nextStepKey);
        if (!next || next.entityKey === step.entityKey) continue;
        const candidates = relationshipByEndpoints.get(`${step.entityKey}\u0000${next.entityKey}`) ?? [];
        const existing = candidates.find((candidate) => candidate.relationshipType === "data") ?? candidates[0];
        if (existing) {
          relationshipIds.add(existing.id);
          const flowIds = existing.metadata.flowIds as string[];
          if (!flowIds.includes(flow.flowKey)) flowIds.push(flow.flowKey);
          continue;
        }
        const outputs = parseStringArray(step.outputsJson);
        const inputs = parseStringArray(next.inputsJson);
        const payload = outputs.length > 0 ? outputs.join(" + ") : inputs.join(" + ");
        const relationship: SemanticRelationship = {
          id: `${flow.flowKey}:relationship:${step.stepKey}:${next.stepKey}`,
          sourceObjectId: step.entityKey,
          targetObjectId: next.entityKey,
          relationshipType: "data",
          direction: "directed",
          label: payload || `${step.title} → ${next.title}`,
          summary: `${step.title} → ${next.title}`,
          state: stateFromKnowledge(flow.knowledgeState),
          importance: importance(72),
          metadata: {
            synthetic: true,
            flowIds: [flow.flowKey],
            fromStepId: step.stepKey,
            toStepId: next.stepKey,
          },
          layoutHints: relationshipPortHints("data"),
        };
        relationships.push(relationship);
        relationshipIds.add(relationship.id);
        relationshipByEndpoints.set(`${step.entityKey}\u0000${next.entityKey}`, [relationship]);
      }
    }

    return {
      id: flow.flowKey,
      name: flow.name,
      description: flow.summary,
      objectIds: [...new Set(steps.map((step) => step.entityKey))],
      relationshipIds: [...relationshipIds],
      steps: semanticSteps,
      state: stateFromKnowledge(flow.knowledgeState),
      importance: importance(78),
      metadata: {
        trigger: flow.trigger,
        outcome: flow.outcome,
        knowledgeState: flow.knowledgeState,
        lifecycleStatus: flow.lifecycleStatus,
        sourceObservationId: flow.sourceObservationId,
        validFromRevision: flow.validFromRevision,
        validToRevision: flow.validToRevision,
      },
    };
  });

  return {
    id: `${input.projectId}:r${input.revision}`,
    version: SEMANTIC_GRAPH_VERSION,
    name: input.projectName,
    regions,
    objects,
    relationships,
    flows,
    scope: {
      projectId: input.projectId,
      revision: input.revision,
      kind: "project",
      source: input.source ?? "registry",
    },
    metadata: {
      canonicalEntityCount: input.entities.length,
      canonicalRelationCount: input.relations.length,
      generatedAtRevision: input.revision,
    },
  };
}

