983	.relationship-edge .react-flow__edge-path { fill: none; stroke: #72858a; stroke-linecap: square; stroke-linejoin: round; stroke-width: 1.25; }
984	.relationship-edge.type-control .react-flow__edge-path { stroke-dasharray: 8 4; }
985	.relationship-edge.type-event .react-flow__edge-path { stroke-dasharray: 2 5; stroke-linecap: round; }
986	.relationship-edge.type-dependency .react-flow__edge-path { stroke: #66767b; stroke-dasharray: 5 4; }
987	.relationship-edge.type-external .react-flow__edge-path { stroke: #898f91; stroke-dasharray: 10 3 2 3; }
988	.relationship-edge.emphasis-related .react-flow__edge-path { stroke: #7ea79f; stroke-width: 1.45; }
989	.relationship-edge.emphasis-active .react-flow__edge-path, .relationship-edge.is-selected .react-flow__edge-path { stroke: var(--map-focus-strong); stroke-width: 2.35; }
990	.relationship-edge.emphasis-muted .react-flow__edge-path { stroke: #46555a; stroke-width: .9; }
991	.relationship-edge.emphasis-suppressed .react-flow__edge-path { opacity: .07; stroke-width: .8; }
992	.relationship-label { background: rgba(12,18,21,.96); border: 1px solid var(--map-line-strong); color: var(--map-text-soft); display: flex; font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size: .8125rem; gap: 5px; max-width: 170px; padding: 2px 5px; pointer-events: all; position: absolute; }
993	.relationship-label.active { border-color: rgba(155,210,193,.55); color: var(--map-focus-strong); }
994	.relationship-label b { color: var(--map-focus); }
995	.relationship-label span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
