.relationship-edge.type-external .react-flow__edge-path { stroke: #898f91; stroke-dasharray: 10 3 2 3; }
.relationship-edge.emphasis-related .react-flow__edge-path { stroke: #7ea79f; stroke-width: 1.45; }
.relationship-edge.emphasis-active .react-flow__edge-path, .relationship-edge.is-selected .react-flow__edge-path { stroke: var(--map-focus-strong); stroke-width: 2.35; }
.relationship-edge.emphasis-muted .react-flow__edge-path { stroke: #46555a; stroke-width: .9; }
.relationship-edge.emphasis-suppressed .react-flow__edge-path { opacity: .07; stroke-width: .8; }
.relationship-label { background: rgba(12,18,21,.96); border: 1px solid var(--map-line-strong); color: var(--map-text-soft); display: flex; font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size: .8125rem; gap: 5px; max-width: 170px; padding: 2px 5px; pointer-events: all; position: absolute; }
.relationship-label.active { border-color: rgba(155,210,193,.55); color: var(--map-focus-strong); }
.relationship-label b { color: var(--map-focus); }
.relationship-label span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.flow-packet { fill: var(--map-focus-strong); filter: none; pointer-events: none; }

