.canvas-reading-key i { display: block; height: 6px; width: 12px; }
.canvas-reading-key .object-key { border: 1px solid #799793; }
.canvas-reading-key .relationship-key { border-top: 1px solid #72858a; height: 1px; }
.canvas-reading-key .trace-key { border-top: 2px solid var(--map-focus-strong); height: 1px; }
