.canvas-inspector { background: rgba(15,22,26,.985); border-left: 1px solid var(--map-line-strong); bottom: 0; color: var(--map-text); overflow-y: auto; position: absolute; right: 0; top: 0; transform: translateX(101%); transition: transform 170ms ease; width: 336px; z-index: 24; }
.canvas-inspector.open { transform: translateX(0); }
.inspector-heading { align-items: flex-start; border-bottom: 1px solid var(--map-line); display: flex; justify-content: space-between; padding: 15px 15px 13px; }
.inspector-heading > div { display: grid; min-width: 0; }
