import { register } from "node:module";
register("./tests/cloudflare-loader.mjs", import.meta.url);

const { CANVAS_FIXTURES } = await import("./app/architecture/fixtures.ts");
const { layoutSemanticGraph } = await import("./app/architecture/layout.ts");

for (const [name, graph] of Object.entries(CANVAS_FIXTURES)) {
  const layout = await layoutSemanticGraph(graph);
  const topLevel = graph.regions.filter((region) => !region.parentRegionId);
  const rects = topLevel.map((region) => layout.regionRects[region.id]).filter(Boolean);
  const xs = [...new Set(rects.map((rect) => Math.round(rect.y / 120)))];
  const minX = Math.min(...rects.map((rect) => rect.x));
  const maxX = Math.max(...rects.map((rect) => rect.x + rect.width));
  const minY = Math.min(...rects.map((rect) => rect.y));
  const maxY = Math.max(...rects.map((rect) => rect.y + rect.height));
  console.log(name, {
    topLevelRegions: rects.length,
    distinctRows: xs.length,
    hullAspect: Math.round((maxX - minX) / (maxY - minY) * 100) / 100,
    layoutW: layout.width,
    layoutH: layout.height,
    overallAspect: Math.round(layout.width / layout.height * 100) / 100,
  });
}

