export const FOUNDATION_VERSION = "v0.2";
export const AGENT_PROTOCOL_VERSION = "v0.3";

export const ONTOLOGY_ENTITY_TYPES = [
  "Project",
  "Domain",
  "Module",
  "Component",
  "Capability",
  "Flow",
  "Interface",
  "DataEntity",
  "Decision",
  "Invariant",
  "Change",
  "Verification",
  "Evidence",
  "AgentSession",
] as const;

export const ONTOLOGY_RELATION_TYPES = [
  "contains",
  "depends_on",
  "calls",
  "implements",
  "exposes",
  "produces",
  "consumes",
  "transforms",
  "traverses",
  "owns",
  "constrained_by",
  "affected_by",
  "verified_by",
  "supported_by",
] as const;

export const ARCHITECTURE_FLOW_ROLES = [
  "entry",
  "producer",
  "transformer",
  "router",
  "guard",
  "consumer",
  "side_effect",
  "exit",
] as const;

export const KNOWLEDGE_STATES = [
  "AUTHORITATIVE",
  "CONFIRMED",
  "INFERRED",
  "UNKNOWN",
  "STALE",
  "CONFLICTED",
] as const;

export type KnowledgeState = (typeof KNOWLEDGE_STATES)[number];

export const CHANGE_STATES = [
  "CREATED",
  "SCOPING",
  "PLANNED",
  "EXECUTING",
  "VERIFYING",
  "REVIEWING",
  "COMPLETED",
  "REJECTED",
] as const;

export type ChangeState = (typeof CHANGE_STATES)[number];

export const ENGINEERING_EVENT_TYPES = [
  "ProjectRegistered",
  "ChangeCreated",
  "ScopeIdentified",
  "ObservationRecorded",
  "FactProposed",
  "FactConfirmed",
  "FactInvalidated",
  "DecisionRecorded",
  "ImplementationStarted",
  "ArtifactModified",
  "VerificationStarted",
  "VerificationPassed",
  "VerificationFailed",
  "RiskRaised",
  "ContextInvalidated",
  "ChangeCompleted",
  "ContextCompiled",
  "AgentHandshakeCompleted",
  "ChangeStateTransitioned",
  "ReconciliationDecided",
  "RevisionPublished",
] as const;

export type EngineeringEventType = (typeof ENGINEERING_EVENT_TYPES)[number];

export const KNOWLEDGE_TRANSITIONS: Record<KnowledgeState, readonly KnowledgeState[]> = {
  AUTHORITATIVE: ["STALE", "CONFLICTED"],
  CONFIRMED: ["AUTHORITATIVE", "STALE", "CONFLICTED"],
  INFERRED: ["CONFIRMED", "STALE", "CONFLICTED"],
  UNKNOWN: ["INFERRED", "CONFIRMED", "AUTHORITATIVE"],
  STALE: ["INFERRED", "CONFIRMED", "AUTHORITATIVE", "CONFLICTED"],
  CONFLICTED: ["INFERRED", "CONFIRMED", "AUTHORITATIVE", "STALE"],
};

export const CHANGE_TRANSITIONS: Record<ChangeState, readonly ChangeState[]> = {
  CREATED: ["SCOPING", "REJECTED"],
  SCOPING: ["PLANNED", "REJECTED"],
  PLANNED: ["EXECUTING", "REJECTED"],
  EXECUTING: ["VERIFYING", "REJECTED"],
  VERIFYING: ["EXECUTING", "REVIEWING", "REJECTED"],
  REVIEWING: ["EXECUTING", "COMPLETED", "REJECTED"],
  COMPLETED: [],
  REJECTED: [],
};

export function canTransitionKnowledge(from: KnowledgeState, to: KnowledgeState) {
  return from === to || KNOWLEDGE_TRANSITIONS[from].includes(to);
}

export function canTransitionChange(from: ChangeState, to: ChangeState) {
  return from === to || CHANGE_TRANSITIONS[from].includes(to);
}

export function assertKnowledgeTransition(from: KnowledgeState, to: KnowledgeState) {
  if (!canTransitionKnowledge(from, to)) {
    throw new Error(`INVALID_KNOWLEDGE_TRANSITION:${from}->${to}`);
  }
}

export function assertChangeTransition(from: ChangeState, to: ChangeState) {
  if (!canTransitionChange(from, to)) {
    throw new Error(`INVALID_CHANGE_TRANSITION:${from}->${to}`);
  }
}

export type EngineeringEventEnvelope = {
  id: string;
  eventType: EngineeringEventType;
  projectId: string;
  projectRevision: number;
  changeId?: string;
  actor: string;
  involvedEntities: string[];
  evidenceRefs: string[];
  reason: string;
  severity: "info" | "warning" | "error";
  correlationId?: string;
  causationId?: string;
};

