47	function intersects(left: LayoutRect, right: LayoutRect, padding = 22) {
48	  return left.x < right.x + right.width + padding
49	    && left.x + left.width + padding > right.x
50	    && left.y < right.y + right.height + padding
51	    && left.y + left.height + padding > right.y;
52	}
53	
54	function stabilizeIncrementalLayout(graph: SemanticGraph, previous: CanvasLayout, next: CanvasLayout): CanvasLayout {
55	  if (previous.fingerprint === next.fingerprint) return { ...previous, durationMs: 0 };
56	  const graphObjectIds = new Set(graph.objects.map((object) => object.id));
57	  const commonObjectIds = Object.keys(previous.objectRects).filter((id) => graphObjectIds.has(id) && next.objectRects[id]);
58	  const priorObjectCount = Object.keys(previous.objectRects).length;
59	  if (priorObjectCount === 0 || commonObjectIds.length / priorObjectCount < .8) return next;
60	
61	  const objectRects: Record<string, LayoutRect> = {};
62	  for (const id of commonObjectIds) {
63	    const prior = previous.objectRects[id];
64	    const measured = next.objectRects[id];
65	    objectRects[id] = { ...measured, x: prior.x, y: prior.y };
66	  }
67	
68	  const additionsByRegion = new Map<string, number>();
69	  for (const object of graph.objects) {
70	    if (objectRects[object.id]) continue;
71	    const measured = next.objectRects[object.id];
72	    if (!measured) continue;
73	    const previousRegion = previous.regionRects[object.regionId];
74	    const nextRegion = next.regionRects[object.regionId];
75	    let candidate = previousRegion && nextRegion
76	      ? { ...measured, x: previousRegion.x + measured.x - nextRegion.x, y: previousRegion.y + measured.y - nextRegion.y }
77	      : measured;
78	    if (Object.values(objectRects).some((rect) => intersects(candidate, rect))) {
79	      const additionIndex = additionsByRegion.get(object.regionId) ?? 0;
80	      additionsByRegion.set(object.regionId, additionIndex + 1);
81	      const anchor = previousRegion ?? nextRegion;
82	      candidate = {
83	        ...measured,
84	        x: (anchor?.x ?? 0) + (anchor?.width ?? 0) + 52,
85	        y: (anchor?.y ?? 0) + 54 + additionIndex * (measured.height + 28),
86	      };
87	    }
88	    objectRects[object.id] = candidate;
89	  }
90	
91	  const regionRects: Record<string, RegionLayoutRect> = {};
92	  for (const region of graph.regions) {
93	    regionRects[region.id] = previous.regionRects[region.id] ?? next.regionRects[region.id];
94	  }
95	  for (const object of graph.objects) {
96	    const objectRect = objectRects[object.id];
97	    const regionRect = regionRects[object.regionId];
98	    if (!objectRect || !regionRect) continue;
99	    const right = Math.max(regionRect.x + regionRect.width, objectRect.x + objectRect.width + 26);
100	    const bottom = Math.max(regionRect.y + regionRect.height, objectRect.y + objectRect.height + 26);
101	    regionRects[object.regionId] = { ...regionRect, width: right - regionRect.x, height: bottom - regionRect.y };
102	  }
103	
104	  const relationshipRoutes: Record<string, RelationshipRoute> = {};
105	  for (const relationship of graph.relationships) {
106	    const previousRoute = previous.relationshipRoutes[relationship.id];
107	    const sourcePrevious = previous.objectRects[relationship.sourceObjectId];
108	    const targetPrevious = previous.objectRects[relationship.targetObjectId];
109	    const sourceNext = objectRects[relationship.sourceObjectId];
110	    const targetNext = objectRects[relationship.targetObjectId];
111	    const geometryUnchanged = sourcePrevious && targetPrevious && sourceNext && targetNext
112	      && sourcePrevious.x === sourceNext.x && sourcePrevious.y === sourceNext.y
113	      && sourcePrevious.width === sourceNext.width && sourcePrevious.height === sourceNext.height
114	      && targetPrevious.x === targetNext.x && targetPrevious.y === targetNext.y
115	      && targetPrevious.width === targetNext.width && targetPrevious.height === targetNext.height;
116	    if (previousRoute && geometryUnchanged) relationshipRoutes[relationship.id] = previousRoute;
117	  }
118	
119	  const allRects = [...Object.values(objectRects), ...Object.values(regionRects)];
120	  const width = Math.max(next.width, ...allRects.map((rect) => rect.x + rect.width + 42));
121	  const height = Math.max(next.height, ...allRects.map((rect) => rect.y + rect.height + 42));
122	  return { ...next, width, height, objectRects, regionRects, relationshipRoutes };
123	}
