export const DIRECT_UNIT_KEY = "__direct__";

export function topLevelUnitRegionIds(graph: SemanticGraph): string[] {
  const top = graph.regions.filter((region) => !region.parentRegionId);
  const packingParentId = top.length === 1 ? top[0].id : null;
  return graph.regions
    .filter((region) => (region.parentRegionId ?? null) === packingParentId)
    .sort((left, right) => (left.order ?? 0) - (right.order ?? 0) || left.id.localeCompare(right.id))
    .map((region) => region.id);
}

export function topLevelUnitIndex(graph: SemanticGraph): Map<string, string> {
  const unitIds = new Set(topLevelUnitRegionIds(graph));
  const regionById = new Map(graph.regions.map((region) => [region.id, region]));
  const unitByRegion = new Map<string, string>();
  for (const region of graph.regions) {
    const seen = new Set<string>();
    let cursor: SemanticRegion | undefined = region;
    while (cursor && !unitIds.has(cursor.id) && !seen.has(cursor.id)) {
      seen.add(cursor.id);
      cursor = cursor.parentRegionId ? regionById.get(cursor.parentRegionId) : undefined;
    }
    unitByRegion.set(region.id, cursor && unitIds.has(cursor.id) ? cursor.id : DIRECT_UNIT_KEY);
  }
  const result = new Map<string, string>();
  for (const object of graph.objects) {
    result.set(object.id, unitByRegion.get(object.regionId) ?? DIRECT_UNIT_KEY);
  }
  return result;
}

function buildPortSpecs(relationships: SemanticRelationship[], orientation: LayoutOrientation) {
  const portsByObject = new Map<string, PortSpec[]>();
  const relationshipPorts = new Map<string, { sourcePortId: string; targetPortId: string; sourceSide: SemanticPortSide; targetSide: SemanticPortSide }>();
  const orderedRelationships = [...relationships].sort((left, right) =>
    (left.layoutHints?.order ?? 0) - (right.layoutHints?.order ?? 0) || left.id.localeCompare(right.id));
  const sideCounts = new Map<string, number>();

