const MAP_ASPECT_TARGET = 1.7;
const UNIT_GAP_X = 110;
const UNIT_GAP_Y = 96;
const MAP_MARGIN = 42;

function packUnits(sizes: Array<{ width: number; height: number }>) {
  const totalArea = sizes.reduce((sum, size) => sum + (size.width + UNIT_GAP_X) * (size.height + UNIT_GAP_Y), 0);
  const targetWidth = Math.max(1300, Math.sqrt(totalArea * MAP_ASPECT_TARGET));
  const rows: Array<Array<{ index: number; width: number; height: number }>> = [[]];
  let rowWidth = 0;
  sizes.forEach((size, index) => {
    const current = rows.at(-1)!;
    const projected = rowWidth + (current.length > 0 ? UNIT_GAP_X : 0) + size.width;
    if (current.length > 0 && projected > targetWidth) {
      rows.push([{ index, width: size.width, height: size.height }]);
      rowWidth = size.width;
      return;
    }
    current.push({ index, width: size.width, height: size.height });
    rowWidth = projected;
  });
  const rowWidths = rows.map((row) => row.reduce((sum, entry, position) => sum + entry.width + (position > 0 ? UNIT_GAP_X : 0), 0));
  const mapWidth = Math.max(1, ...rowWidths);
  const offsets: Array<{ x: number; y: number }> = sizes.map(() => ({ x: 0, y: 0 }));
  let y = 0;
  rows.forEach((row, rowIndex) => {
    const rowHeight = Math.max(1, ...row.map((entry) => entry.height));
    let x = (mapWidth - rowWidths[rowIndex]) / 2;
    for (const entry of row) {
      offsets[entry.index] = { x, y };
      x += entry.width + UNIT_GAP_X;
    }
    y += rowHeight + UNIT_GAP_Y;
  });
  return { offsets, width: mapWidth, height: Math.max(1, y - UNIT_GAP_Y) };
}

type UnitLayoutResult = {
  key: string;
  width: number;
  height: number;
  objectRects: Record<string, LayoutRect>;
  regionRects: Record<string, RegionLayoutRect>;
  relationshipRoutes: Record<string, RelationshipRoute>;
};

export async function layoutSemanticGraph(
  graph: SemanticGraph,
  options: { orientation?: LayoutOrientation; previousLayout?: CanvasLayout } = {},
): Promise<CanvasLayout> {
  const started = typeof performance === "undefined" ? Date.now() : performance.now();
  const fingerprint = semanticGraphFingerprint(graph);
  if (options.previousLayout?.fingerprint === fingerprint) return { ...options.previousLayout, graphId: graph.id, fingerprint, durationMs: 0 };
  const orientation = options.orientation ?? "RIGHT";
  const objectOrder = stableObjectOrder(graph, options.previousLayout);
  const regionById = new Map(graph.regions.map((region) => [region.id, region]));
  const objectsByRegion = new Map<string, typeof graph.objects>();
  const childRegions = new Map<string | null, SemanticRegion[]>();
  for (const object of graph.objects) objectsByRegion.set(object.regionId, [...(objectsByRegion.get(object.regionId) ?? []), object]);
  for (const region of graph.regions) childRegions.set(region.parentRegionId ?? null, [...(childRegions.get(region.parentRegionId ?? null) ?? []), region]);

  const buildObjectNode = (object: SemanticGraph["objects"][number], portsByObject: Map<string, PortSpec[]>): ElkNode => {
    const size = objectSize(object.name, object.summary);
    return {
      id: object.id,
      width: size.width,
      height: size.height,
      ports: (portsByObject.get(object.id) ?? []).sort((left, right) => left.side.localeCompare(right.side) || left.order - right.order).map(asElkPort),
      layoutOptions: {
        "elk.portConstraints": "FIXED_ORDER",
        "elk.layered.priority.direction": String(Math.round(object.importance.score)),
      },
    };
  };

  const buildRegion = (region: SemanticRegion, portsByObject: Map<string, PortSpec[]>): ElkNode => {
    const depth = regionDepth(region, regionById);
    const nestedRegions = [...(childRegions.get(region.id) ?? [])]
      .sort((left, right) => (left.order ?? 0) - (right.order ?? 0) || left.id.localeCompare(right.id))
      .map((nested) => buildRegion(nested, portsByObject));
    const objects = [...(objectsByRegion.get(region.id) ?? [])]
      .sort((left, right) => (objectOrder.get(left.id) ?? 0) - (objectOrder.get(right.id) ?? 0) || left.id.localeCompare(right.id))
      .map((object) => buildObjectNode(object, portsByObject));
    return {
      id: region.id,
      children: [...nestedRegions, ...objects],
      layoutOptions: regionOptions(orientation, depth),
    };
  };

  const top = graph.regions.filter((region) => !region.parentRegionId);
  const packingParentId = top.length === 1 ? top[0].id : null;
  const unitOfObject = topLevelUnitIndex(graph);

  type Unit = { key: string; region?: SemanticRegion; objects: SemanticGraph["objects"]; relationships: SemanticRelationship[] };
  const units: Unit[] = topLevelUnitRegionIds(graph).map((unitId) => ({
    key: unitId,
    region: regionById.get(unitId),
    objects: graph.objects.filter((object) => unitOfObject.get(object.id) === unitId),
    relationships: graph.relationships.filter((relationship) =>
      unitOfObject.get(relationship.sourceObjectId) === unitId && unitOfObject.get(relationship.targetObjectId) === unitId),
  }));
  const directObjects = graph.objects.filter((object) => unitOfObject.get(object.id) === DIRECT_UNIT_KEY);
  if (directObjects.length > 0) {
    units.push({
      key: DIRECT_UNIT_KEY,
      objects: directObjects,
      relationships: graph.relationships.filter((relationship) =>
        unitOfObject.get(relationship.sourceObjectId) === DIRECT_UNIT_KEY && unitOfObject.get(relationship.targetObjectId) === DIRECT_UNIT_KEY),
    });
  }

  const unitRootOptions: Record<string, string> = {
    "elk.algorithm": "layered",
    "elk.direction": orientation,
    "elk.edgeRouting": "ORTHOGONAL",
    "elk.hierarchyHandling": "INCLUDE_CHILDREN",
    "elk.separateConnectedComponents": "false",
    "elk.spacing.componentComponent": "72",
    "elk.spacing.edgeNode": "28",
    "elk.spacing.labelNode": "18",
    "elk.spacing.edgeLabel": "12",
    "elk.edgeLabels.inline": "true",
    "elk.layered.unnecessaryBendpoints": "true",
    "elk.layered.thoroughness": graph.objects.length >= 80 ? "3" : "7",
    "elk.padding": "[top=42,left=42,bottom=42,right=42]",
  };

  const layoutUnit = async (unit: Unit): Promise<UnitLayoutResult> => {
    const { portsByObject, relationshipPorts } = buildPortSpecs(unit.relationships, orientation);
    const root: ElkNode = unit.region
      ? buildRegion(unit.region, portsByObject)
      : {
          id: `unit:${unit.key}`,
          children: [...unit.objects]
            .sort((left, right) => (objectOrder.get(left.id) ?? 0) - (objectOrder.get(right.id) ?? 0) || left.id.localeCompare(right.id))
            .map((object) => buildObjectNode(object, portsByObject)),
          layoutOptions: regionOptions(orientation, 0),
        };
    const elkEdges: ElkEdge[] = unit.relationships.map((relationship) => {
      const ports = relationshipPorts.get(relationship.id);
      const label = relationship.label?.trim();
      const flowIds = Array.isArray(relationship.metadata.flowIds) ? relationship.metadata.flowIds : [];
      const includeLabelInLayout = graph.objects.length <= 60 || flowIds.length > 0;
      const labelSize = label && includeLabelInLayout ? edgeLabelSize(label) : null;
      return {
        id: relationship.id,
        sources: [ports?.sourcePortId ?? relationship.sourceObjectId],
        targets: [ports?.targetPortId ?? relationship.targetObjectId],
        labels: label && labelSize ? [{ id: `${relationship.id}:label`, text: label, ...labelSize }] : [],
      };
    });

    const output = await elk.layout({
      id: `${graph.id}:unit:${unit.key}`,
      layoutOptions: unitRootOptions,
      children: [root],
      edges: elkEdges,
    } as unknown as Parameters<typeof elk.layout>[0]) as unknown as ElkNode;

    const unitObjectRects: Record<string, LayoutRect> = {};
    const unitRegionRects: Record<string, RegionLayoutRect> = {};
    const absoluteOffsetById = new Map<string, { x: number; y: number }>([[output.id, { x: 0, y: 0 }]]);
    const objectIds = new Set(unit.objects.map((object) => object.id));

    const visit = (node: ElkNode, parentOffset: { x: number; y: number }) => {
      const x = parentOffset.x + (node.x ?? 0);
      const y = parentOffset.y + (node.y ?? 0);
      absoluteOffsetById.set(node.id, { x, y });
      if (objectIds.has(node.id)) unitObjectRects[node.id] = { id: node.id, x, y, width: node.width ?? 0, height: node.height ?? 0 };
      const region = regionById.get(node.id);
      if (region) {
        unitRegionRects[node.id] = {
          id: node.id,
          x,
          y,
          width: node.width ?? 0,
          height: node.height ?? 0,
          depth: regionDepth(region, regionById),
          parentRegionId: region.parentRegionId,
        };
      }
      for (const child of node.children ?? []) visit(child, { x, y });
    };
    visit(output, { x: 0, y: 0 });

    const outputEdges: ElkEdge[] = [];
    const collectEdges = (node: ElkNode) => {
      outputEdges.push(...(node.edges ?? []));
      for (const child of node.children ?? []) collectEdges(child);
    };
    collectEdges(output);

    const unitRoutes: Record<string, RelationshipRoute> = {};
    for (const edge of outputEdges) {
      if (!unit.relationships.some((candidate) => candidate.id === edge.id)) continue;
      const ports = relationshipPorts.get(edge.id);
      const offset = absoluteOffsetById.get(edge.container ?? output.id) ?? { x: 0, y: 0 };
      const points: Array<{ x: number; y: number }> = [];
      for (const section of edge.sections ?? []) {
        const sectionPoints = [section.startPoint, ...(section.bendPoints ?? []), section.endPoint]
          .filter((point): point is ElkPoint => Boolean(point))
          .map((point) => ({ x: offset.x + (point.x ?? 0), y: offset.y + (point.y ?? 0) }));
        if (points.length > 0 && sectionPoints.length > 0) {
          const previous = points.at(-1)!;
          const next = sectionPoints[0];
          if (previous.x === next.x && previous.y === next.y) sectionPoints.shift();
        }
        points.push(...sectionPoints);
      }
      const label = edge.labels?.[0];
      unitRoutes[edge.id] = {
        id: edge.id,
        points,
        labelPoint: label
          ? { x: offset.x + (label.x ?? 0) + label.width / 2, y: offset.y + (label.y ?? 0) + label.height / 2 }
          : routeMidpoint(points),
        sourceSide: ports?.sourceSide ?? "right",
        targetSide: ports?.targetSide ?? "left",
      };
    }

    return {
      key: unit.key,
      width: output.width ?? 0,
      height: output.height ?? 0,
      objectRects: unitObjectRects,
      regionRects: unitRegionRects,
      relationshipRoutes: unitRoutes,
    };
  };

  const unitResults = await Promise.all(units.map(layoutUnit));

  const packed = packUnits(unitResults.map((result) => ({ width: result.width, height: result.height })));
  const unitFrames = unitResults.map((result, index) => ({ x: packed.offsets[index].x, y: packed.offsets[index].y, width: result.width, height: result.height }));
  const minX = Math.min(...unitFrames.map((frame) => frame.x));
  const minY = Math.min(...unitFrames.map((frame) => frame.y));
  const maxX = Math.max(...unitFrames.map((frame) => frame.x + frame.width));
  const maxY = Math.max(...unitFrames.map((frame) => frame.y + frame.height));
  const wrapperPacked = packingParentId && regionById.get(packingParentId)
    ? { x: minX - 36, y: minY - 64, width: maxX - minX + 72, height: maxY - minY + 100 }
    : null;
  const translate = {
    x: MAP_MARGIN - (wrapperPacked?.x ?? 0),
    y: MAP_MARGIN - (wrapperPacked?.y ?? 0),
  };

  const objectRects: Record<string, LayoutRect> = {};
  const regionRects: Record<string, RegionLayoutRect> = {};
  const relationshipRoutes: Record<string, RelationshipRoute> = {};
  unitResults.forEach((result, index) => {
    const offset = { x: packed.offsets[index].x + translate.x, y: packed.offsets[index].y + translate.y };
    for (const [id, rect] of Object.entries(result.objectRects)) objectRects[id] = { ...rect, x: rect.x + offset.x, y: rect.y + offset.y };
    for (const [id, rect] of Object.entries(result.regionRects)) regionRects[id] = { ...rect, x: rect.x + offset.x, y: rect.y + offset.y };
    for (const [id, route] of Object.entries(result.relationshipRoutes)) {
      relationshipRoutes[id] = {
        ...route,
        points: route.points.map((point) => ({ x: point.x + offset.x, y: point.y + offset.y })),
        labelPoint: route.labelPoint ? { x: route.labelPoint.x + offset.x, y: route.labelPoint.y + offset.y } : undefined,
      };
    }
  });
  if (wrapperPacked) {
    regionRects[packingParentId!] = {
      id: packingParentId!,
      x: wrapperPacked.x + translate.x,
      y: wrapperPacked.y + translate.y,
      width: wrapperPacked.width,
      height: wrapperPacked.height,
      depth: 0,
      parentRegionId: undefined,
    };
  }

  const finished = typeof performance === "undefined" ? Date.now() : performance.now();
  const result: CanvasLayout = {
    graphId: graph.id,
    fingerprint,
    orientation,
    width: (wrapperPacked?.width ?? packed.width) + MAP_MARGIN * 2,
    height: (wrapperPacked?.height ?? packed.height) + MAP_MARGIN * 2,
    durationMs: Math.round((finished - started) * 100) / 100,
    objectRects,
    regionRects,
    relationshipRoutes,
  };
  return options.previousLayout ? stabilizeIncrementalLayout(graph, options.previousLayout, result) : result;
}

