if (interaction.mode === "trace" && interaction.activeFlowId) {
  const flow = index.flowById.get(interaction.activeFlowId);
  const orderedSteps = [...(flow?.steps ?? [])].sort((left, right) => left.sequence - right.sequence || left.id.localeCompare(right.id));
  const flowObjectIds = new Set(flow?.objectIds ?? []);
  const flowRelationshipIds = new Set(flow?.relationshipIds ?? []);
  const contextIds = neighbors(graph, flowObjectIds);

  const mainPathRelationshipIds = new Set<string>();
  const relationshipByEndpoints = new Map(graph.relationships
    .filter((relationship) => flowRelationshipIds.has(relationship.id))
    .map((relationship) => [`${relationship.sourceObjectId}�${relationship.targetObjectId}`, relationship]));
  for (let stepIndex = 0; stepIndex < orderedSteps.length - 1; stepIndex += 1) {
    const relationship = relationshipByEndpoints.get(`${orderedSteps[stepIndex].objectId}�${orderedSteps[stepIndex + 1].objectId}`);
    if (relationship) mainPathRelationshipIds.add(relationship.id);
  }

  const traceOrder = new Map<string, TraceStepReading>();
  const traceEntryIds = new Set<string>();
  const traceExitIds = new Set<string>();
  orderedSteps.forEach((step, stepIndex) => {
    const entry = step.role === "entry" || stepIndex === 0;
    const exit = step.role === "exit" || stepIndex === orderedSteps.length - 1;
    const existing = traceOrder.get(step.objectId);
    if (!existing || step.sequence < existing.sequence) {
      traceOrder.set(step.objectId, { sequence: step.sequence, role: step.role, title: step.title, entry, exit });
    } else if (entry) existing.entry = true;
    else if (exit) existing.exit = true;
    if (entry) traceEntryIds.add(step.objectId);
    if (exit) traceExitIds.add(step.objectId);
  });

  for (const object of graph.objects) {
    if (flowObjectIds.has(object.id)) objectEmphasis.set(object.id, "primary");
    else if (contextIds.has(object.id)) objectEmphasis.set(object.id, "context");
    else objectEmphasis.set(object.id, "muted");
  }
  for (const objectId of flowObjectIds) focusObjectIds.add(objectId);
  for (const relationship of graph.relationships) {
    if (mainPathRelationshipIds.has(relationship.id)) {
      relationshipEmphasis.set(relationship.id, "active");
      activeRelationshipIds.add(relationship.id);
    } else if (flowRelationshipIds.has(relationship.id)) {
      relationshipEmphasis.set(relationship.id, "related");
    } else if (flowObjectIds.has(relationship.sourceObjectId) || flowObjectIds.has(relationship.targetObjectId)) {
      relationshipEmphasis.set(relationship.id, "related");
    } else {
      relationshipEmphasis.set(relationship.id, "suppressed");
    }
  }
  viewModelTrace.order = traceOrder;
  viewModelTrace.entryIds = traceEntryIds;
  viewModelTrace.exitIds = traceExitIds;
  viewModelTrace.mainPath = mainPathRelationshipIds;
}

