export function visibleRelationshipIds(graph: SemanticGraph, view: CanvasViewModel) {
  if (view.zoomLevel === "component" || view.zoomLevel === "operational") {
    return new Set(graph.relationships.map((relationship) => relationship.id));
  }
  const unitOfObject = topLevelUnitIndex(graph);
  const emphasisDriven: string[] = [];
  const candidates: Array<{ id: string; score: number }> = [];
  for (const relationship of graph.relationships) {
    const emphasis = view.relationshipEmphasis.get(relationship.id) ?? "normal";
    const selected = view.selection?.kind === "relationship" && view.selection.id === relationship.id;
    if (emphasis === "active" || emphasis === "related" || selected) {
      emphasisDriven.push(relationship.id);
      continue;
    }
    if (view.zoomLevel === "landscape") {
      if (relationship.importance.level !== "critical") continue;
    } else if (
      relationship.importance.level !== "critical"
      && relationship.importance.level !== "high"
      && unitOfObject.get(relationship.sourceObjectId) === unitOfObject.get(relationship.targetObjectId)
    ) continue;
    const crossUnitBonus = unitOfObject.get(relationship.sourceObjectId) !== unitOfObject.get(relationship.targetObjectId) ? 40 : 0;
    candidates.push({ id: relationship.id, score: relationship.importance.score + crossUnitBonus });
  }
  const budget = view.zoomLevel === "landscape" ? LANDSCAPE_EDGE_BUDGET : ARCHITECTURE_EDGE_BUDGET;
  const ranked = candidates.sort((left, right) => right.score - left.score || left.id.localeCompare(right.id)).slice(0, budget);
  return new Set([...emphasisDriven, ...ranked.map((candidate) => candidate.id)]);
}

