const unitResults = await Promise.all(units.map(async (unit) => {
  const primary = await layoutUnit(unit, orientation);
  const aspect = primary.width / Math.max(1, primary.height);
  // Sparse intra-unit topology can collapse layered layout into a single tall
  // strip; flowing the unit the other way restores a two-dimensional map tile.
  if (aspect < 0.55 && primary.height > 900 && unit.objects.length > 3 && orientation === "RIGHT") {
    const rotated = await layoutUnit(unit, "DOWN");
    if (rotated.width / Math.max(1, rotated.height) > aspect) return rotated;
  }
  return primary;
}));

