import assert from "node:assert/strict";
import { register } from "node:module";
import test from "node:test";

register("./cloudflare-loader.mjs", import.meta.url);

const {
  ARCHITECTURE_MIN_ZOOM,
  ARCHITECTURE_EDGE_BUDGET,
  LANDSCAPE_EDGE_BUDGET,
  defaultCanvasZoom,
  dockPanViewport,
  objectLabelScale,
  regionLabelScale,
} = await import("../app/architecture/readability.ts");
const { deriveCanvasView, semanticZoomLevel, visibleRelationshipIds } = await import("../app/architecture/interaction.ts");
const { CANVAS_FIXTURES, LARGE_CANVAS_FIXTURE, MEDIUM_CANVAS_FIXTURE, SMALL_CANVAS_FIXTURE } = await import("../app/architecture/fixtures.ts");
const { layoutSemanticGraph, topLevelUnitIndex, topLevelUnitRegionIds } = await import("../app/architecture/layout.ts");

test("default camera zoom stays at Architecture density and fills the viewport", () => {
  const viewport = { width: 1600, height: 900 };
  const scales = [
    { name: "small", width: 2200, height: 1500 },
    { name: "medium", width: 5800, height: 3800 },
    { name: "large", width: 9000, height: 8400 },
  ];
  for (const scale of scales) {
    const zoom = defaultCanvasZoom(scale, viewport);
    assert.ok(zoom >= ARCHITECTURE_MIN_ZOOM, `${scale.name}: default zoom ${zoom} must stay at or above the Architecture floor`);
    assert.notEqual(semanticZoomLevel(zoom), "landscape", `${scale.name}: default view must not open in Landscape`);
    const coverage = Math.max((scale.width * zoom) / viewport.width, (scale.height * zoom) / viewport.height);
    assert.ok(coverage >= .82, `${scale.name}: content should occupy most of the viewport, got ${coverage}`);
  }
  const tiny = defaultCanvasZoom({ width: 900, height: 500 }, viewport);
  assert.ok(tiny <= 1.05 && tiny >= ARCHITECTURE_MIN_ZOOM, "default zoom must respect the max zoom ceiling");
});

test("label compensation keeps screen-space text readable at map densities", () => {
  for (const zoom of [.16, .24, .3, .42, .48, .55, .62, .79]) {
    const level = semanticZoomLevel(zoom);
    const objectScale = objectLabelScale(level, zoom);
    const regionScale = regionLabelScale(level, zoom);
    const objectScreen = 15 * zoom * objectScale;
    const regionScreen = 13 * zoom * regionScale;
    if (level === "landscape" || level === "architecture") {
      assert.ok(objectScreen >= 11.5, `object label at zoom ${zoom} must stay readable, got ${objectScreen}px`);
      assert.ok(regionScreen >= 10.5, `region label at zoom ${zoom} must stay readable, got ${regionScreen}px`);
    }
    assert.ok(objectScale >= 1 && regionScale >= 1, "compensation never shrinks labels");
  }
  assert.equal(objectLabelScale("component", 1), 1);
  assert.equal(regionLabelScale("operational", 1.4), 1);
  assert.ok(objectLabelScale("landscape", .05) <= 4.5 + 1e-9, "object label compensation respects its cap");
  assert.ok(regionLabelScale("architecture", .2) <= 3.2 + 1e-9, "region label compensation respects its cap");
});

test("docked inspector pans the camera without changing zoom or collapsing the map", () => {
  const zoom = .72;
  const container = { width: 1200, height: 800 };
  const nodeAtRight = { x: 1500, y: 400, width: 280, height: 130 };
  const panned = dockPanViewport({ x: 0, y: 0, zoom }, nodeAtRight, container);
  assert.ok(panned, "a node hidden behind the dock must trigger a pan");
  assert.equal(panned.zoom, zoom, "docking must never change zoom");
  const screenRight = (nodeAtRight.x + nodeAtRight.width) * zoom + panned.x;
  const screenLeft = nodeAtRight.x * zoom + panned.x;
  assert.ok(screenRight <= container.width - 40 && screenLeft >= 8, "panned node must be fully inside the effective viewport");

  const visible = { x: 200, y: 300, width: 280, height: 130 };
  assert.equal(dockPanViewport({ x: 40, y: 20, zoom }, visible, container), null, "already-visible nodes must not move the camera");
  assert.equal(dockPanViewport({ x: 0, y: 0, zoom }, null, container), null, "no focus rect means no camera change");

  const huge = { x: 0, y: 0, width: 4000, height: 200 };
  const centered = dockPanViewport({ x: 0, y: 0, zoom }, huge, container);
  assert.ok(centered, "oversized focus rects still produce a pan");
});

test("edge visibility enforces architecture-level density budgets", () => {
  const browse = (zoom) => deriveCanvasView(MEDIUM_CANVAS_FIXTURE, { mode: "browse", selection: null, activeFlowId: null, zoom, searchQuery: "" });
  const architectureView = browse(.6);
  const architectureEdges = visibleRelationshipIds(MEDIUM_CANVAS_FIXTURE, architectureView);
  assert.ok(architectureEdges.size < MEDIUM_CANVAS_FIXTURE.relationships.length, "Architecture density must hide low-value topology");
  assert.ok(architectureEdges.size <= ARCHITECTURE_EDGE_BUDGET, `Architecture edge budget is ${ARCHITECTURE_EDGE_BUDGET}, got ${architectureEdges.size}`);

  const landscapeView = browse(.3);
  const landscapeEdges = visibleRelationshipIds(MEDIUM_CANVAS_FIXTURE, landscapeView);
  assert.ok(landscapeEdges.size <= LANDSCAPE_EDGE_BUDGET, `Landscape edge budget is ${LANDSCAPE_EDGE_BUDGET}, got ${landscapeEdges.size}`);

  const selected = MEDIUM_CANVAS_FIXTURE.objects[0];
  const inspectView = deriveCanvasView(MEDIUM_CANVAS_FIXTURE, { mode: "inspect", selection: { kind: "object", id: selected.id }, activeFlowId: null, zoom: .3, searchQuery: "" });
  for (const relationship of MEDIUM_CANVAS_FIXTURE.relationships) {
    const incident = relationship.sourceObjectId === selected.id || relationship.targetObjectId === selected.id;
    if (incident) assert.ok(inspectView.relationshipEmphasis.get(relationship.id) === "active" && visibleRelationshipIds(MEDIUM_CANVAS_FIXTURE, inspectView).has(relationship.id), "inspect emphasis must survive any zoom");
  }

  const componentView = browse(1);
  assert.equal(visibleRelationshipIds(MEDIUM_CANVAS_FIXTURE, componentView).size, MEDIUM_CANVAS_FIXTURE.relationships.length, "component density shows all relationships");
});

test("trace reading exposes an ordered main path with entry and exit", () => {
  const flow = SMALL_CANVAS_FIXTURE.flows[0];
  const view = deriveCanvasView(SMALL_CANVAS_FIXTURE, { mode: "trace", selection: { kind: "flow", id: flow.id }, activeFlowId: flow.id, zoom: .6, searchQuery: "" });
  const ordered = [...flow.steps].sort((left, right) => left.sequence - right.sequence);
  for (const step of ordered) {
    const reading = view.traceOrder.get(step.objectId);
    assert.ok(reading, `object ${step.objectId} must carry trace step info`);
  }
  const sequences = [...view.traceOrder.values()].map((entry) => entry.sequence);
  assert.deepEqual([...sequences].sort((left, right) => left - right), sequences, "trace order must follow step sequence");
  assert.ok(view.traceEntryIds.size >= 1, "trace must mark the entry object");
  assert.ok(view.traceExitIds.size >= 1, "trace must mark the result object");
  assert.ok(view.traceEntryIds.has(ordered[0].objectId), "entry marker belongs to the first ordered step");
  assert.ok(view.traceExitIds.has(ordered.at(-1).objectId), "exit marker belongs to the last ordered step");
  assert.ok(view.mainPathRelationshipIds.size >= ordered.length - 2, "main path must connect the ordered steps");
  for (const relationshipId of view.mainPathRelationshipIds) {
    assert.equal(view.relationshipEmphasis.get(relationshipId), "active", "main path relationships lead the corridor");
  }
});

test("top-level regions compose a two-dimensional map, not a strip", { timeout: 60_000 }, async () => {
  for (const name of ["medium", "large", "complex"]) {
    const graph = CANVAS_FIXTURES[name];
    const unitIndex = topLevelUnitIndex(graph);
    const units = topLevelUnitRegionIds(graph);
    const layout = await layoutSemanticGraph(graph);
    assert.ok(units.length >= 3, `${name}: expected multiple top-level units, got ${units.length}`);
    const unitRects = units.map((id) => layout.regionRects[id]).filter(Boolean);
    const rows = new Set(unitRects.map((rect) => Math.round(rect.y / 400)));
    assert.ok(rows.size >= 2, `${name}: top-level regions must occupy at least two rows, got ${rows.size}`);
    const minX = Math.min(...unitRects.map((rect) => rect.x));
    const maxX = Math.max(...unitRects.map((rect) => rect.x + rect.width));
    const minY = Math.min(...unitRects.map((rect) => rect.y));
    const maxY = Math.max(...unitRects.map((rect) => rect.y + rect.height));
    const hullAspect = (maxX - minX) / (maxY - minY);
    assert.ok(hullAspect >= .55 && hullAspect <= 2.6, `${name}: map hull aspect ${hullAspect} must stay map-like`);

    let crossUnit = 0;
    for (const relationship of graph.relationships) {
      if (unitIndex.get(relationship.sourceObjectId) !== unitIndex.get(relationship.targetObjectId)) crossUnit += 1;
    }
    assert.ok(crossUnit >= 1, `${name}: fixtures must exercise cross-unit relationships`);
    assert.equal(Object.keys(layout.relationshipRoutes).length, graph.relationships.length - crossUnit, `${name}: only intra-unit relationships carry ELK routes`);

    const rects = Object.values(layout.objectRects);
    for (let left = 0; left < rects.length; left += 1) {
      for (let right = left + 1; right < rects.length; right += 1) {
        const a = rects[left];
        const b = rects[right];
        const overlap = a.x < b.x + b.width + 2 && a.x + a.width + 2 > b.x && a.y < b.y + b.height + 2 && a.y + a.height + 2 > b.y;
        assert.equal(overlap, false, `${name}: objects ${a.id}/${b.id} overlap after packing`);
      }
    }
  }
});

