import type { SemanticZoomLevel } from "./interaction";

export const ARCHITECTURE_MIN_ZOOM = 0.55;
export const TRACE_FIT_MIN_ZOOM = 0.5;
export const FOCUS_FIT_MIN_ZOOM = 0.5;
export const ARCHITECTURE_EDGE_BUDGET = 48;
export const LANDSCAPE_EDGE_BUDGET = 26;
export const LABEL_SCREEN_TARGET = 0.85;

export function defaultCanvasZoom(
  content: { width: number; height: number },
  viewport: { width: number; height: number },
  options: { padding?: number; minZoom?: number; maxZoom?: number } = {},
) {
  const padding = options.padding ?? 0.1;
  const minZoom = options.minZoom ?? ARCHITECTURE_MIN_ZOOM;
  const maxZoom = options.maxZoom ?? 1.05;
  const usableWidth = Math.max(1, viewport.width * (1 - padding * 2));
  const usableHeight = Math.max(1, viewport.height * (1 - padding * 2));
  const fit = Math.min(usableWidth / Math.max(1, content.width), usableHeight / Math.max(1, content.height));
  return Math.round(Math.min(maxZoom, Math.max(minZoom, fit)) * 1000) / 1000;
}

export function objectLabelScale(zoomLevel: SemanticZoomLevel, zoom: number) {
  if (zoomLevel === "landscape") return Math.min(4.5, Math.max(1, LABEL_SCREEN_TARGET / Math.max(zoom, 0.16)));
  if (zoomLevel === "architecture") return Math.min(2.4, Math.max(1, LABEL_SCREEN_TARGET / Math.max(zoom, 0.42)));
  return 1;
}

export function regionLabelScale(zoomLevel: SemanticZoomLevel, zoom: number) {
  if (zoomLevel === "landscape" || zoomLevel === "architecture") {
    return Math.min(3.2, Math.max(1, LABEL_SCREEN_TARGET / Math.max(zoom, 0.2)));
  }
  return 1;
}

export type ViewportTransform = { x: number; y: number; zoom: number };

export type WorldRect = { x: number; y: number; width: number; height: number };

export function dockPanViewport(
  viewport: ViewportTransform,
  focusRect: WorldRect | null,
  container: { width: number; height: number },
  margin = 48,
): ViewportTransform | null {
  if (!focusRect) return null;
  const { zoom } = viewport;
  const screenLeft = focusRect.x * zoom + viewport.x;
  const screenRight = (focusRect.x + focusRect.width) * zoom + viewport.x;
  const screenTop = focusRect.y * zoom + viewport.y;
  const screenBottom = (focusRect.y + focusRect.height) * zoom + viewport.y;
  const maxX = container.width - margin;
  const maxY = container.height - margin;
  if (screenLeft >= margin && screenRight <= maxX && screenTop >= margin && screenBottom <= maxY) return null;

  const panXMin = margin - focusRect.x * zoom;
  const panXMax = maxX - (focusRect.x + focusRect.width) * zoom;
  const panYMin = margin - focusRect.y * zoom;
  const panYMax = maxY - (focusRect.y + focusRect.height) * zoom;
  const nextX = panXMin > panXMax ? (panXMin + panXMax) / 2 : Math.min(panXMax, Math.max(panXMin, viewport.x));
  const nextY = panYMin > panYMax ? (panYMin + panYMax) / 2 : Math.min(panYMax, Math.max(panYMin, viewport.y));
  if (Math.abs(nextX - viewport.x) < 1 && Math.abs(nextY - viewport.y) < 1) return null;
  return { x: Math.round(nextX), y: Math.round(nextY), zoom };
}

