"use client";

import type { CSSProperties } from "react";
import type { Node, NodeProps } from "@xyflow/react";
import { regionLabelScale } from "./readability";
import type { RegionNodeData } from "./types";

export type ArchitectureRegionNode = Node<RegionNodeData, "region">;

export default function RegionNode({ data }: NodeProps<ArchitectureRegionNode>) {
  const { region, emphasis, zoomLevel, zoom, objectCount, childRegionCount, summaryNames, depth } = data;
  const labelScale = regionLabelScale(zoomLevel, zoom);
  const summary = summaryNames.length > 0 ? summaryNames.join(" · ") : "";
  return (
    <section
      aria-label={`Region ${region.name}`}
      className={`canvas-region depth-${Math.min(depth, 3)} emphasis-${emphasis} zoom-${zoomLevel}`}
      style={{ "--region-label-scale": labelScale } as CSSProperties}
    >
      <header>
        <span>Region</span>
        <strong>{region.name}</strong>
        <small>
          {objectCount} objects{childRegionCount > 0 ? ` · ${childRegionCount} regions` : ""}
        </small>
      </header>
      {zoomLevel === "landscape" && summary && (
        <p className="canvas-region-summary" aria-label="Region summary">
          {summary}
          {objectCount > summaryNames.length ? ` <span>+${objectCount - summaryNames.length}</span>` : ""}
        </p>
      )}
    </section>
  );
}

