export type ArchitectureFlowNode = Node<ObjectNodeData, "object">;

export default function ObjectNode({ data, selected }: NodeProps<ArchitectureFlowNode>) {
  const { object, emphasis, zoomLevel, zoom, incomingCount, outgoingCount, flowSteps } = data;
  const showState = zoomLevel !== "landscape";
  const showSummary = zoomLevel === "component" || zoomLevel === "operational";
