await mkdir(outputDirectory, { recursive: true });

const smallLayout = await layoutSemanticGraph(SMALL_CANVAS_FIXTURE);
const smallView = deriveCanvasView(SMALL_CANVAS_FIXTURE, { mode: "browse", selection: null, activeFlowId: null, zoom: .72, searchQuery: "" });
await writeFile(path.join(outputDirectory, "canvas-engine-v1-small-browse.svg"), render(
  SMALL_CANVAS_FIXTURE,
  smallLayout,
  smallView,
  "Canvas Engine v1 · Small / Browse",
  "Actual fixture geometry · full topology · quiet regions · normal relationship grammar",
));

const complexLayout = await layoutSemanticGraph(COMPLEX_CANVAS_FIXTURE);
const complexFlow = COMPLEX_CANVAS_FIXTURE.flows[0];
const complexView = deriveCanvasView(COMPLEX_CANVAS_FIXTURE, { mode: "trace", selection: { kind: "flow", id: complexFlow.id }, activeFlowId: complexFlow.id, zoom: .24, searchQuery: "" });
