  complexView,
  "Canvas Engine v1 · Complex / Trace",
  "Actual fixture geometry · nested regions · high fan-in/out · long labels · unrelated relationships suppressed",
));

console.log(JSON.stringify({
  small: { layoutMs: smallLayout.durationMs, width: smallLayout.width, height: smallLayout.height },
  complex: { layoutMs: complexLayout.durationMs, width: complexLayout.width, height: complexLayout.height },
