() => {
  const viewport = document.querySelector(".react-flow__viewport");
  const zoomMatch = viewport ? viewport.style.transform.match(/scale\(([\d.]+)\)/) : null;
  const zoom = zoomMatch ? Number(zoomMatch[1]) : null;
  const label = document.querySelector(".object-node .object-label");
  const labelStyle = label ? getComputedStyle(label) : null;
  const labelScale = label ? (label.style.getPropertyValue("--label-scale") || 1) : null;
  const regionName = document.querySelector(".canvas-region > header strong");
  const regionStyle = regionName ? getComputedStyle(regionName) : null;
  const regionScale = document.querySelector(".canvas-region")?.style.getPropertyValue("--region-label-scale") || 1;
  const objectCount = document.querySelectorAll(".object-node").length;
  const edgeCount = document.querySelectorAll(".relationship-edge").length;
  const regionCount = document.querySelectorAll(".canvas-region").length;
  const stage = document.querySelector(".canvas-stage");
  const statusbar = document.querySelector(".canvas-statusbar")?.textContent;
  return {
    zoom,
    objectLabelPx: labelStyle ? labelStyle.fontSize : null,
    objectLabelScreenPx: labelStyle ? Math.round(parseFloat(labelStyle.fontSize) * parseFloat(labelScale) * zoom * 10) / 10 : null,
    regionNamePx: regionStyle ? regionStyle.fontSize : null,
    regionNameScreenPx: regionStyle ? Math.round(parseFloat(regionStyle.fontSize) * parseFloat(regionScale) * zoom * 10) / 10 : null,
    objectCount, edgeCount, regionCount,
    stageColumns: stage ? getComputedStyle(stage).gridTemplateColumns : null,
    statusbar,
  };
}

