input.function:
() => {
  const viewport = document.querySelector(".react-flow__viewport");
  const zoom = Number(viewport.style.transform.match(/scale\(([\d.]+)\)/)[1]);
  const measure = (selector) => {
    const el = document.querySelector(selector);
    if (!el) return null;
    const fontSize = parseFloat(getComputedStyle(el).fontSize);
    const transform = getComputedStyle(el).transform;
    const scale = transform && transform !== "none" ? Number(transform.match(/matrix\(([\d.]+),/)[1]) : 1;
    return { fontSize, cssScale: Math.round(scale * 100) / 100, screenPx: Math.round(fontSize * scale * zoom * 10) / 10 };
  };
  return {
    zoom,
    objectLabel: measure(".object-node .object-label"),
    regionName: measure(".canvas-region > header strong"),
    regionSummaryVisible: Boolean(document.querySelector(".canvas-region-summary")),
  };
}

