() => {
  const zoom = Number(document.querySelector(".react-flow__viewport").style.transform.match(/scale\(([\d.]+)\)/)[1]);
  const label = document.querySelector(".object-node .object-label");
  const region = document.querySelector(".canvas-region > header strong");
  const measure = (el) => {
    if (!el) return null;
    const fontSize = parseFloat(getComputedStyle(el).fontSize);
    const transform = getComputedStyle(el).transform;
    const scale = transform && transform !== "none" ? Number(transform.match(/matrix\(([\d.]+),/)[1]) : 1;
    return Math.round(fontSize * scale * zoom * 10) / 10;
  };
  const topRegions = [...document.querySelectorAll(".canvas-region")].filter((node) => {
    const rect = node.getBoundingClientRect();
    return rect.width > 400;
  }).map((node) => ({
    name: node.querySelector("strong")?.textContent,
    y: Math.round(node.getBoundingClientRect().top),
    screenW: Math.round(node.getBoundingClientRect().width),
  }));
  return {
    zoom,
    objectLabelScreenPx: measure(label),
    regionNameScreenPx: measure(region),
    visibleObjects: document.querySelectorAll(".object-node").length,
    visibleEdges: document.querySelectorAll(".relationship-edge").length,
    largeRegions: topRegions.length,
    regionRows: [...new Set(topRegions.map((r) => Math.round(r.y / 300)))].length,
    topRegions,
    status: document.querySelector(".canvas-statusbar")?.textContent,
  };
}

