() => {
  const zoom = Number(document.querySelector(".react-flow__viewport").style.transform.match(/scale\(([\d.]+)\)/)[1]);
  const label = document.querySelector(".object-node .object-label");
  const fontSize = parseFloat(getComputedStyle(label).fontSize);
  const transform = getComputedStyle(label).transform;
  const scale = transform !== "none" ? Number(transform.match(/matrix\(([\d.]+),/)[1]) : 1;
  const regionsInView = [...document.querySelectorAll(".canvas-region > header strong")].filter((el) => {
    const rect = el.getBoundingClientRect();
    return rect.top >= 0 && rect.top < 955 && rect.right > 0 && rect.left < 1720;
  }).map((el) => el.textContent);
  const allRegionTops = [...document.querySelectorAll(".canvas-region.depth-1 > header strong, .canvas-region.depth-2 > header strong")].map((el) => Math.round(el.getBoundingClientRect().top));
  return {
    zoom,
    objectLabelScreenPx: Math.round(fontSize * scale * zoom * 10) / 10,
    zoomLevel: document.querySelector(".canvas-statusbar span")?.textContent,
    regionsInView,
    distinctRows: [...new Set(allRegionTops.map((top) => Math.round(top / 300)))].length,
    edgesInDom: document.querySelectorAll(".relationship-edge").length,
  };
}

